import java.util.*;
import java.util.concurrent.*;
public class Main { public static void main(String[] args) { Scanner s=new Scanner(System.in);int n=s.nextInt();int[] values=new int[n];for(int i=0;i<n;i++)values[i]=s.nextInt();List<CompletableFuture<Integer>> fs=new ArrayList<>();for(int value:values)fs.add(CompletableFuture.supplyAsync(()->value*2).thenApply(x->x+1));for(var f:fs)System.out.println(f.join());} }

