import java.util.*;
import java.util.concurrent.*;
public class Main { public static void main(String[] args) throws Exception { Scanner s=new Scanner(System.in);int n=s.nextInt();List<String> words=new ArrayList<>();for(int i=0;i<n;i++)words.add(s.next());try(ExecutorService executor=Executors.newVirtualThreadPerTaskExecutor()){List<Future<String>> fs=new ArrayList<>();for(String word:words)fs.add(executor.submit(()->word.toUpperCase(Locale.ROOT)+":"+Thread.currentThread().isVirtual()));for(Future<String> f:fs)System.out.println(f.get());}} }

